import {MATERIALS,BEAMS} from './presets.js';
import {createTransportView} from './transport-view.js';
import {VERSION,MAX_TRACKS,validate,empty,merge} from './engine.js';
const $=id=>document.getElementById(id),fmt=n=>Math.round(n).toLocaleString(),colors={transmitted:'#26ddb1',absorbed:'#ff597b',reflected:'#ad7eff',capped:'#a9bbcf',scatter:'#ffb74a',source:'#b6dcff'};
let current=null,records=[],running=false,benchmarking=false,stopStory=false,logs=[],tourStep=0;
const CHUNK=4096;
for(const [id,items] of [['material',MATERIALS],['particle',BEAMS]]){const selected=$(id).value;$(id).replaceChildren(...Object.entries(items).map(([value,p])=>{const option=document.createElement('option');option.value=value;option.textContent=p.name;return option;}));$(id).value=selected;}
function presetNotes(){const m=MATERIALS[$('material').value]||MATERIALS.custom,b=BEAMS[$('particle').value]||BEAMS.neutral;$('materialNote').textContent=m.note+' Illustrative coefficients.';$('beamNote').textContent=b.note+' Species presets set energy and beam color; the same teaching transport model is used.';}
presetNotes();
const transportView=createTransportView($('tracks'),{pause:$('motionPause'),speed:$('motionSpeed'),density:$('motionDensity'),trails:$('motionTrails'),replay:$('replay'),note:$('motionNote')});
$('particle').onchange=()=>{$('energy').value=BEAMS[$('particle').value].energy;presetNotes();};
// Nonzero minimums must not shift the HTML number-step grid.
for(const id of ['thickness','energy','sigma'])$(id).step='any';
for(const [id,title,note] of [['memoryChart','Peak process memory','Native only · MB'],['cpuChart','Compute activity','Native CPU % / browser occupancy %']]){const article=document.createElement('article'),h=document.createElement('h3'),small=document.createElement('small'),canvas=document.createElement('canvas');h.textContent=title;small.textContent=note;h.append(small);canvas.id=id;canvas.className='chart';canvas.setAttribute('role','img');canvas.setAttribute('aria-label',title);article.append(h,canvas);document.querySelector('.benchcharts').append(article);}
function params(){return validate(Object.fromEntries(['n','seed','thickness','sigma','absorb','energy'].map(k=>[k,Number($(k).value)])));}
function readConfig(){return {...params(),material:$('material').value,particle:$('particle').value};}
function setConfig(p){for(const k of ['n','seed','thickness','sigma','absorb','energy','material','particle'])if(p[k]!==undefined)$(k).value=p[k];$('pout').value=p.absorb;presetNotes();}
function tab(id){document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===id));document.querySelectorAll('[data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===id));requestAnimationFrame(render);}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));document.querySelectorAll('[data-n]').forEach(b=>b.onclick=()=>{$('n').value=b.dataset.n;});
$('absorb').oninput=()=>$('pout').value=$('absorb').value;
$('material').onchange=()=>{const m=MATERIALS[$('material').value];if(m.sigma!==undefined){$('sigma').value=m.sigma;$('absorb').value=m.absorb;$('pout').value=m.absorb;}presetNotes();};
function log(s){logs.push(`${new Date().toLocaleTimeString()}  ${s}`);if(logs.length>120)logs.shift();$('logs').textContent=logs.join('\n');$('logs').scrollTop=$('logs').scrollHeight;}
function lock(on){running=on;document.querySelectorAll('#controls input,#controls select,#controls button[data-n]').forEach(e=>e.disabled=on||benchmarking);$('run').disabled=on||benchmarking;$('bench').disabled=on||benchmarking;$('stop').disabled=!on;$('resume').disabled=on||benchmarking;}
function signature(p){return [VERSION,p.n,p.seed,p.thickness,p.sigma,p.absorb,p.energy,p.particle||'neutral'].join('|');}
function save(name,data){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function run(p,w,resume=null){if(running)return Promise.reject(Error('A run is already active'));validate(p);if(!Number.isInteger(w)||w<1||w>32)return Promise.reject(Error('Invalid worker count'));
 return new Promise((resolve,reject)=>{const t0=performance.now();current={p,w,result:resume?.result||empty(),completed:new Set(resume?.completed||[]),jobs:[],active:0,next:0,pause:false,elapsed:resume?.elapsed||0,busy:resume?.busy||0,workerMs:Array(w).fill(0),init:0,mergeMs:0,checkpoint:!!resume};const c=current;logs=[];lock(true);$('sceneEmpty').hidden=true;$('sceneCaption').textContent=`${p.thickness} cm · ${p.material||'custom'}`;$('heatEnd').textContent=p.thickness+' cm';log(`Run ${VERSION}; seed ${p.seed}; ${fmt(p.n)} histories; ${w} worker(s).`);log(`Chunk size ${CHUNK}; up to 384 sampled histories; all histories tallied.`);transportView.reset();const totalChunks=Math.ceil(p.n/CHUNK);let settled=false;
 function finish(error){if(settled)return;settled=true;c.elapsed+=performance.now()-t0;c.jobs.forEach(j=>j.worker.terminate());lock(false);if(error){log('ERROR '+error.message);$('status').textContent='Failed: '+error.message;reject(error);return;}const complete=c.result.done===p.n;c.complete=complete;$('status').textContent=complete?'Complete · all histories calculated':'Paused · checkpoint ready';log(`${complete?'Completed':'Paused'} ${fmt(c.result.done)} histories in ${(c.elapsed/1000).toFixed(3)} s.`);if(complete){const rec={schema:1,model:VERSION,engine:'browser',environment:'local',machine:navigator.userAgent,params:p,workers:w,ranks:1,threads:w,wallSeconds:c.elapsed/1000,throughput:p.n/(c.elapsed/1000),occupancy:c.busy/(w*c.elapsed),cpuUtilization:null,memoryMB:null,resumed:!!resume,counts:Object.fromEntries(['transmitted','absorbed','reflected','capped','scatter','collisions'].map(k=>[k,c.result[k]])),timestamp:new Date().toISOString()};records.push(rec);renderBench();}render();resolve(complete);}
 function dispatch(job){while(c.next<totalChunks&&c.completed.has(c.next))c.next++;if(c.pause||c.next>=totalChunks){job.label='idle';if(c.active===0)finish();return;}const i=c.next++,start=i*CHUNK,end=Math.min(p.n,start+CHUNK);job.chunk=i;job.label=`histories ${fmt(start)}–${fmt(end-1)}`;c.active++;job.worker.postMessage({p,start,end,worker:job.id});}
 try{for(let i=0;i<w;i++){const worker=new Worker('./worker.js',{type:'module'}),job={id:i,worker,label:'starting',chunk:null};c.jobs.push(job);worker.onerror=e=>finish(Error(e.message||'Worker failed'));worker.onmessage=({data:d})=>{if(settled)return;if(d.error){finish(Error(d.error));return;}c.active--;const mt=performance.now();merge(c.result,d.result);c.mergeMs+=performance.now()-mt;c.completed.add(job.chunk);c.busy+=d.ms;c.workerMs[i]+=d.ms;if(c.completed.size<=8||c.completed.size%50===0)log(`Worker ${i}: [${d.start}, ${d.end}) finished in ${d.ms.toFixed(2)} ms; checkpoint ${c.completed.size}/${totalChunks}.`);dispatch(job);if(!settled){c.liveElapsed=c.elapsed+performance.now()-t0;update();}};}c.init=performance.now()-t0;c.jobs.forEach(dispatch);update();}catch(e){finish(e);}
 });}
$('controls').onsubmit=async e=>{e.preventDefault();if(running||benchmarking)return;try{tab('simulation');await run(readConfig(),Number($('workers').value));}catch(e){$('status').textContent=e.message;}};
$('stop').onclick=()=>{if(current&&running){current.pause=true;stopStory=true;$('status').textContent='Pausing after in-flight chunks…';log('Pause requested; in-flight chunks will finish.');}};
function update(){if(!current)return;const c=current,r=c.result,p=c.p,elapsed=(running?c.liveElapsed||0:c.elapsed)/1000;$('progress').value=r.done/p.n;$('progressText').textContent=`${fmt(r.done)} / ${fmt(p.n)}`;if(running)$('status').textContent=`Running · ${c.w} workers · seed ${p.seed}`;for(const k of ['transmitted','absorbed','reflected','scatter']){$(k).textContent=fmt(r[k]);if($(k+'Pct'))$(k+'Pct').textContent=(r.done?100*r[k]/r.done:0).toFixed(1)+'%';}$('total').innerHTML=fmt(r.done)+'<small>histories completed</small>';const a=r.done?100*r.transmitted/r.done:0,b=r.done?100*r.absorbed/r.done:0,d=r.done?100*r.reflected/r.done:0;$('donut').style.background=`conic-gradient(${colors.transmitted} 0% ${a}%,${colors.absorbed} ${a}% ${a+b}%,${colors.reflected} ${a+b}% ${a+b+d}%,#64748b ${a+b+d}% 100%)`;$('balance').textContent=`${fmt(r.capped)} capped · ${(r.deposited/(r.done*p.energy||1)*100).toFixed(1)}% energy deposited. Scattering counts events.`;$('runtime').textContent=elapsed.toFixed(3)+' s';$('throughput').textContent=elapsed?fmt(r.done/elapsed):'—';$('path').textContent=(r.path/(r.done||1)).toFixed(2)+' cm';$('collisions').textContent=(r.collisions/(r.done||1)).toFixed(2);$('occupancy').textContent=elapsed?(Math.min(1,c.busy/(c.w*elapsed*1000))*100).toFixed(1)+'%':'—';$('jobs').replaceChildren(...c.jobs.map(j=>{const el=document.createElement('div');el.textContent=`Worker ${j.id} · ${running?j.label:'stopped'} · ${(c.workerMs[j.id]/1000).toFixed(3)} s compute`;return el;}));$('profile').textContent=`Seed: ${p.seed}\nCompleted chunks: ${c.completed.size} / ${Math.ceil(p.n/CHUNK)}\nCompute summed: ${(c.busy/1000).toFixed(4)} s\nWorker construction: ${c.init.toFixed(2)} ms\nTally merge: ${c.mergeMs.toFixed(2)} ms\nWall: ${elapsed.toFixed(4)} s (includes startup/messages)\nCollisions: ${fmt(r.collisions)}\nEnergy in: ${(r.done*p.energy).toFixed(3)} MeV\nDeposited: ${r.deposited.toFixed(3)} MeV\nEscaped: ${r.escaped.toFixed(3)} MeV\nResidual: ${r.residual.toFixed(3)} MeV\nMemory: unavailable in browser\nBounded tallies; no per-history storage beyond sample.`;$('trace').textContent=r.trace.length?r.trace.map(t=>`#${t.step}  u=${t.u.toFixed(6)}  flight=${t.distance.toFixed(4)} cm\n    v=${t.choice.toFixed(6)}  x=${t.x.toFixed(4)} cm → ${t.choice<p.absorb?'absorb':'scatter'}`).join('\n'):'History 0 has no recorded collision yet (it may escape directly).';drawHeat();drawDepth();}
function context(id){const canvas=$(id),rect=canvas.getBoundingClientRect();if(!rect.width)return null;const dpr=window.devicePixelRatio||1;if(canvas.width!==Math.round(rect.width*dpr)||canvas.height!==Math.round(rect.height*dpr)){canvas.width=Math.round(rect.width*dpr);canvas.height=Math.round(rect.height*dpr);}const ctx=canvas.getContext('2d');ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,rect.width,rect.height);return [ctx,rect.width,rect.height];}
function drawTracks(now){transportView.draw(now,current);}

function drawHeat(){const v=context('heat');if(!v)return;const [ctx,w,h]=v,a=current?.result.heat||Array(640).fill(0),max=Math.max(1,...a);for(let y=0;y<16;y++)for(let x=0;x<40;x++){const value=a[y*40+x]/max;ctx.fillStyle=value?`hsl(${270-240*Math.sqrt(value)} 90% ${12+55*Math.sqrt(value)}%)`:'#0e2034';ctx.fillRect(x*w/40,y*(h-20)/16,w/40+.5,(h-20)/16+.5);}ctx.fillStyle='#91abc7';ctx.font='10px DM Sans';ctx.fillText(`0 → ${max.toFixed(1)} MeV / cell`,5,h-3);}
function drawDepth(){const v=context('depth');if(!v)return;const [ctx,w,h]=v,a=current?.result.depth||Array(40).fill(0),max=Math.max(1,...a);ctx.strokeStyle='#1d3146';for(let i=0;i<4;i++){ctx.beginPath();ctx.moveTo(0,i*(h-15)/4);ctx.lineTo(w,i*(h-15)/4);ctx.stroke();}a.forEach((n,i)=>{const height=n/max*(h-28);ctx.fillStyle='#ffa747';ctx.fillRect(i*w/40,h-15-height,w/40-2,height);});ctx.fillStyle='#96afc9';ctx.font='10px DM Sans';ctx.fillText(fmt(max)+' max / bin',2,11);}
function render(){update();drawTracks(performance.now());renderBench();}let lastFrame=0;function animate(now){if(now-lastFrame>25){drawTracks(now);lastFrame=now;}requestAnimationFrame(animate);}requestAnimationFrame(animate);window.addEventListener('resize',render);
$('checkpoint').onclick=()=>{if(!current)return alert('Run a simulation first.');const c=current;save('radiant-checkpoint.json',{schema:1,model:VERSION,chunkSize:CHUNK,workers:c.w,params:c.p,completed:[...c.completed],result:c.result,elapsed:running?c.liveElapsed||0:c.elapsed,busy:c.busy});log('Checkpoint exported; only completed chunks included.');};
function checkCheckpoint(v){if(v.schema!==1||v.model!==VERSION||v.chunkSize!==CHUNK)throw Error('Unsupported checkpoint format');validate(v.params);if(!Number.isInteger(v.workers)||v.workers<1||v.workers>32)throw Error("Invalid checkpoint worker count");const r=v.result,ids=v.completed;if(!Array.isArray(ids)||ids.length!==new Set(ids).size||ids.some(i=>!Number.isInteger(i)||i<0||i>=Math.ceil(v.params.n/CHUNK)))throw Error('Invalid completed chunk ranges');const done=ids.reduce((s,i)=>s+Math.min(CHUNK,v.params.n-i*CHUNK),0);if(!r||r.done!==done||r.transmitted+r.absorbed+r.reflected+r.capped!==done)throw Error('Checkpoint counts do not match its ranges');for(const k of ['done','transmitted','absorbed','reflected','capped','scatter','collisions','path','deposited','escaped','residual'])if(!Number.isFinite(r[k])||r[k]<0)throw Error('Invalid checkpoint counters');if(!Array.isArray(r.heat)||r.heat.length!==640||!Array.isArray(r.depth)||r.depth.length!==40||[...r.heat,...r.depth].some(n=>!Number.isFinite(n)||n<0)||!Array.isArray(r.tracks)||r.tracks.length>MAX_TRACKS||!Array.isArray(r.trace)||r.trace.length>12||!Number.isFinite(v.elapsed)||v.elapsed<0||!Number.isFinite(v.busy)||v.busy<0)throw Error('Invalid checkpoint data');r.tracks=[];r.trace=[];return v;}
$('resume').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('Checkpoint exceeds 5 MB');const c=checkCheckpoint(JSON.parse(await file.text()));setConfig(c.params);tab('simulation');await run(c.params,c.workers,c);}catch(e){alert(e.message);}finally{$('resume').value='';}};
function groupRecords(){const groups=new Map();for(const r of records){const key=[r.engine,r.environment,r.machine,signature(r.params),r.workers,r.ranks,r.threads,r.compiler,r.resumed].join('|');if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r);}return [...groups.values()].map(rows=>{const times=rows.map(r=>r.wallSeconds).sort((a,b)=>a-b),m=times.length>>1,median=times.length%2?times[m]:(times[m-1]+times[m])/2;return {...rows[rows.length-1],wallSeconds:median,throughput:rows[0].params.n/median,repeats:rows.length,range:[times[0],times.at(-1)]};});}
function baseline(row,rows){return rows.find(b=>b.workers===1&&b.engine===row.engine&&b.environment===row.environment&&b.machine===row.machine&&b.compiler===row.compiler&&signature(b.params)===signature(row.params)&&!b.resumed&&!row.resumed);}
function renderBench(){const rows=groupRecords();const body=$('measurements');body.replaceChildren();if(!rows.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=9;td.textContent='No measurements yet. Run locally or import a native result.';tr.append(td);body.append(tr);}for(const r of rows){const b=baseline(r,rows),speed=b?b.wallSeconds/r.wallSeconds:null,tr=document.createElement('tr');const vals=[`${r.environment} / ${r.engine}${r.resumed?' (resumed)':''}`,fmt(r.params.n),r.workers,`${r.wallSeconds.toFixed(4)} s · ${r.repeats}× [${r.range.map(n=>n.toFixed(4)).join('–')}]`,fmt(r.throughput),speed?speed.toFixed(2)+'×':'—',speed?(speed/r.workers*100).toFixed(1)+'%':'—',r.memoryMB==null?'Unavailable':r.memoryMB.toFixed(1)+' MB',r.engine==='browser'?(r.occupancy*100).toFixed(1)+'% occupancy':r.cpuUtilization==null?'Unavailable':(r.cpuUtilization*100).toFixed(1)+'% CPU'];for(const value of vals){const td=document.createElement('td');td.textContent=value;tr.append(td);}body.append(tr);}plot('throughChart',rows,r=>r.throughput,false);plot('timeChart',rows,r=>r.wallSeconds,true);plot('scaleChart',rows,r=>{const b=baseline(r,rows);return b?b.wallSeconds/r.wallSeconds:null;},false);plot('memoryChart',rows,r=>r.memoryMB??null,false);plot('cpuChart',rows,r=>r.engine==='browser'?r.occupancy*100:r.cpuUtilization==null?null:r.cpuUtilization*100,false);const valid=rows.filter(r=>r.engine==='browser'&&!r.resumed&&r.params.n>=100000);if(valid.length){const largest=Math.max(...valid.map(r=>r.params.n));const best=valid.filter(r=>r.params.n===largest).sort((a,b)=>b.throughput-a.throughput)[0],budget=Math.max(1,Math.min(86400,Number($('budget').value)||60));$('projection').textContent=`Measured at ${fmt(largest)} histories: ${fmt(best.throughput)} histories/s with ${best.workers} worker(s). Estimated ${fmt(best.throughput*budget)} histories in ${budget} s; 1 billion ≈ ${(1e9/best.throughput/60).toFixed(1)} min. Extrapolation assumes unchanged throughput; thermal limits and contention may change it.`;}}
function plot(id,rows,fn,logScale){const v=context(id);if(!v)return;const [ctx,w,h]=v,rs=rows.slice(-12).map(r=>({r,value:fn(r)})).filter(x=>x.value!==null);ctx.fillStyle='#849bb7';ctx.font='10px DM Sans';if(!rs.length){ctx.fillText('Awaiting comparable measurements',10,h/2);return;}const transform=n=>logScale?Math.log10(1+n*1000):n,max=Math.max(...rs.map(x=>transform(x.value)),.00001);rs.forEach(({r,value},i)=>{const bw=w/rs.length,bh=transform(value)/max*(h-45);ctx.fillStyle=r.environment==='hpc'?'#ffb74a':r.engine==='browser'?'#6daeff':'#b383ff';ctx.fillRect(i*bw+3,h-27-bh,bw-7,bh);ctx.save();ctx.translate(i*bw+bw/2,h-12);ctx.textAlign='center';ctx.fillStyle='#9cb2cd';ctx.fillText(`${r.workers}w`,0,0);ctx.fillText(value>=100?fmt(value):value.toFixed(2),0,-bh-20);ctx.restore();});}
$('budget').oninput=renderBench;
$('bench').onclick=async()=>{if(running||benchmarking)return;let p;try{p=readConfig();}catch(e){alert(e.message);return;}benchmarking=true;stopStory=false;tab('benchmark');let completed=0;try{for(const n of [10000,100000,1000000])for(const w of [1,2,4])for(let repeat=0;repeat<3;repeat++){if(stopStory)break;$('benchStatus').textContent=`Measuring ${fmt(n)} histories · ${w} worker(s) · repeat ${repeat+1}/3 (${completed}/27 runs complete)`;const done=await run({...p,n},w);if(!done){stopStory=true;break;}completed++;} }catch(e){$('benchStatus').textContent='Benchmark failed: '+e.message;}finally{benchmarking=false;lock(false);$('benchStatus').textContent=`${stopStory?'Stopped':'Finished'} · ${completed}/27 complete measurements. Table shows medians and observed ranges.`;renderBench();}};
$('export').onclick=()=>save('radiant-measurements.json',{schema:1,records});
function validateRecord(r){if(r.schema!==1||r.model!==VERSION||!['browser','native'].includes(r.engine)||!['local','hpc'].includes(r.environment))throw Error('Unsupported measurement format');validate(r.params);for(const k of ['wallSeconds','workers'])if(!Number.isFinite(r[k])||r[k]<=0)throw Error('Invalid timing or worker count');if(!Number.isInteger(r.workers)||r.workers>1000000)throw Error('Invalid worker count');if(typeof r.machine!=='string'||r.machine.length>500)throw Error('Missing machine provenance');for(const k of ['occupancy','cpuUtilization','memoryMB'])if(r[k]!=null&&(!Number.isFinite(r[k])||r[k]<0))throw Error('Invalid resource metric');if(r.engine==='browser'&&r.occupancy==null)throw Error('Missing occupancy');r.throughput=r.params.n/r.wallSeconds;return r;}
$('import').onchange=async e=>{try{const fresh=[];for(const f of e.target.files){if(f.size>5e6)throw Error('Measurement exceeds 5 MB');const data=JSON.parse(await f.text());const list=Array.isArray(data.records)?data.records:[data];if(list.length>10000)throw Error('Too many measurements');fresh.push(...list.map(validateRecord));}records.push(...fresh);renderBench();$('benchStatus').textContent=`Imported ${fresh.length} measurements. Machine and environment labels come from the imported file; cluster access is not verified.`;}catch(e){alert(e.message);}finally{$('import').value='';}};
const guide=[['Choose the experiment','Start with 100,000 histories and the concrete illustration. Thickness and cross section control how likely a collision is. Keep the seed fixed to repeat the same histories.','simulation'],['Run and follow a particle','Press Run simulation. Every history is calculated, but up to 384 sampled histories are drawn. Use speed, density and pause controls to follow the looping bombardment. Playback repeats the sample without changing results.','simulation'],['Open the computation','Inspect real random numbers, chunk assignments, elapsed compute time, counters and logs. Pause or export a checkpoint to resume the remaining work.','compute'],['Measure your PC','Run the guided benchmark. It repeats workloads at different worker counts and shows measured speedups. More workers can be slower for small problems.','benchmark'],['Bring your HPC evidence','Build the native backend from the source bundle, measure the same input with 1 thread and with OpenMP/MPI, then import its JSON. No HPC performance is prefilled.','benchmark']];
function showGuide(){const [title,text,id]=guide[tourStep];tab(id);$('tourTitle').textContent=title;$('tourText').textContent=text;$('tourNext').textContent=tourStep===guide.length-1?'Finish':'Next';if(!$('tourDialog').open)$('tourDialog').showModal();}$('tour').onclick=()=>{tourStep=0;showGuide();};$('tourNext').onclick=()=>{if(++tourStep>=guide.length)$('tourDialog').close();else showGuide();};$('tourClose').onclick=()=>$('tourDialog').close();$('hardware').textContent=`${navigator.hardwareConcurrency||'?'} logical CPUs reported · browser workers`;
render();
